"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Bármely szoba: expedíciós látótávolság +{0}, kezdő pontszorzó +{1}. „Sors / Különleges” szobában: az expedíciós térkép kezdettől teljesen látható, pontszorzó további +{2}.",
