"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Bármely szoba: expedíciós egységek életereje +{0}%. „Egészségügy” szobában: kórházi gyógyítás +{1}%, a vezér naponta további {2}%-ot gyógyul.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Bármely szoba: tervrajz-esési esély +{0}%. „Sci-fi” szobában: bázis +{1} lélekszilánk naponta.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Bármely szoba: tervrajz-esési esély +{0}%. „Kovácsolás” szobában: kovácsoláskor {1}% eséllyel még egy jár.",
