"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Bármely szoba: építési idő felére csökken, elkészültkor {0}% ellátmány visszajár. „Csoda” szobában: a visszatérítés {1}%-ra nő.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Bármely szoba: minden védőtorony sebzése +{0}%. „Fegyver” szobában: hatótáv +{1}, támadási sebesség +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Bármely szoba: ásási költség -{0}%. „Különleges” szobában: minden építés {1} nappal rövidebb.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Bármely szoba: kezdő pontszorzó csatánként +{0}. „Kovácsolás” szobában: kovácsolt ereklyék minősége mindig +{1}.",
