"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Bármely szoba: vezér támadása +{0}%. „Fegyver” szobában: sebzés +{1}%, minden támadás láncvillámot old ki ({2} ellenségre ugrik).",
